package com.projexa.coaching.students.service;
import com.projexa.coaching.common.exceptions.ApiException; import com.projexa.coaching.common.tenant.TenantContextHolder; import com.projexa.coaching.students.entity.Student; import com.projexa.coaching.students.repository.StudentRepository; import org.springframework.stereotype.Service; import java.util.*;
@Service public class StudentService { private final StudentRepository repo; public StudentService(StudentRepository repo){this.repo=repo;} public List<Student> list(){return repo.findAllByTenantId(TenantContextHolder.getRequired());} public Student get(UUID id){return repo.findByIdAndTenantId(id,TenantContextHolder.getRequired()).orElseThrow(()->new ApiException("NOT_FOUND","Resource not found"));} public Student create(Student item){item.setTenantId(TenantContextHolder.getRequired()); return repo.save(item);} public Student update(UUID id,Student item){Student current=get(id); copy(item,current); return repo.save(current);} public void delete(UUID id){repo.delete(get(id));} private void copy(Student s,Student t){t.setAdmissionNumber(s.getAdmissionNumber());t.setFirstName(s.getFirstName());t.setLastName(s.getLastName());t.setEmail(s.getEmail());t.setPhone(s.getPhone());t.setDateOfBirth(s.getDateOfBirth());t.setGender(s.getGender());t.setAddress(s.getAddress());t.setProfilePhotoUrl(s.getProfilePhotoUrl());t.setStatus(s.getStatus());}}